  "knowledge": "Processing Stage",
  "description": "Illustrates the progression of data processing in archaeological scanning workflows.",
  "definition": "A sequential classification system with defined stages: 'Raw' (unprocessed scan data), 'Aligned' (multiple scans registered together), 'Cleaned' (noise and artifacts removed), 'Meshed' (point cloud converted to polygon mesh), and 'Textured' (surface textures applied to mesh). Each stage represents a discrete processing milestone."
}

{
  "id": 51,
  "knowledge": "Workflow Efficiency Classification",
  "description": "A standardized categorization system for assessing processing workflow efficiency based on Processing Resource Utilization (PRU) values.",
  "definition": "A three-tier classification where 'Optimized' workflows have \\text{PRU} < 5.0 (highly efficient resource usage), 'Acceptable' workflows have PRU between 5.0-10.0 (reasonable efficiency), and 'Needs Optimization' workflows have PRU > 10.0 (inefficient resource usage requiring intervention). This classification guides processing workflow improvements and resource allocation decisions."
}

{
  "id": 17,
  "knowledge": "Processing Bottleneck",
  "description": "Identifies processing workflows that are experiencing resource constraints using performance metrics.",
  "definition": "A processing record with \\text{PER} < 0.5, where PER is the Processing Efficiency Ratio, indicating potential hardware limitations affecting processing speed and output quality, requiring workflow optimization."
}
